-- P132 V0.1 core tables. P132 objects only.
create table if not exists public."TblP132NewsSource"("SourceID" bigint generated by default as identity primary key,"SourceName" text not null,"FeedURL" text not null unique,"WebsiteURL" text,"DefaultCategory" text,"LanguageCode" text not null default 'zh-TW',"IsActive" boolean not null default true,"LastFetchedAt" timestamptz,"CreatedAt" timestamptz not null default now(),"UpdatedAt" timestamptz not null default now());
create table if not exists public."TblP132Article"("ArticleID" bigint generated by default as identity primary key,"SourceID" bigint not null references public."TblP132NewsSource"("SourceID"),"ExternalID" text,"Title" text not null,"Summary" text,"ContentText" text,"OriginalURL" text not null,"PublishedAt" timestamptz,"Category" text,"LanguageCode" text not null default 'zh-TW',"ContentHash" text,"IsPublished" boolean not null default true,"FetchedAt" timestamptz not null default now(),"CreatedAt" timestamptz not null default now(),unique("SourceID","ExternalID"));
create table if not exists public."TblP132VocabularyConcept"("ConceptID" bigint generated by default as identity primary key,"CanonicalZh" text not null,"MeaningZh" text not null,"PartOfSpeech" text,"Domain" text,"ReviewStatus" text not null default 'approved' check("ReviewStatus" in('pending','approved','rejected')),"IsActive" boolean not null default true,"CreatedAt" timestamptz not null default now(),"UpdatedAt" timestamptz not null default now());
create table if not exists public."TblP132VocabularyForm"("FormID" bigint generated by default as identity primary key,"ConceptID" bigint not null references public."TblP132VocabularyConcept"("ConceptID") on delete cascade,"LanguageCode" text not null check("LanguageCode" in('zh-TW','en','ja')),"SurfaceForm" text not null,"Lemma" text,"Reading" text,"Romanization" text,"PartOfSpeech" text,"IsPreferred" boolean not null default false,"IsActive" boolean not null default true,"CreatedAt" timestamptz not null default now());
create table if not exists public."TblP132ArticleOccurrence"("OccurrenceID" bigint generated by default as identity primary key,"ArticleID" bigint not null references public."TblP132Article"("ArticleID") on delete cascade,"ConceptID" bigint not null references public."TblP132VocabularyConcept"("ConceptID"),"OriginalText" text not null,"StartOffset" integer not null,"EndOffset" integer not null,"SentenceIndex" integer,"ContextText" text,"ReplacementEligible" boolean not null default true,"MatchConfidence" numeric(5,4),"CreatedAt" timestamptz not null default now(),check("StartOffset">=0 and "EndOffset">"StartOffset"),check("MatchConfidence" is null or "MatchConfidence" between 0 and 1),unique("ArticleID","StartOffset","EndOffset"));
create table if not exists public."TblP132LearnerProfile"("UserID" uuid primary key,"TargetLanguage" text not null default 'en' check("TargetLanguage" in('en','ja')),"PreferredInfiltrationRate" numeric(5,4) check("PreferredInfiltrationRate" is null or "PreferredInfiltrationRate" between 0 and 1),"IsActive" boolean not null default true,"CreatedAt" timestamptz not null default now(),"UpdatedAt" timestamptz not null default now());
create table if not exists public."TblP132Exposure"("ExposureID" bigint generated by default as identity primary key,"UserID" uuid not null,"ArticleID" bigint not null references public."TblP132Article"("ArticleID"),"OccurrenceID" bigint not null references public."TblP132ArticleOccurrence"("OccurrenceID"),"ConceptID" bigint not null references public."TblP132VocabularyConcept"("ConceptID"),"DisplayedFormID" bigint not null references public."TblP132VocabularyForm"("FormID"),"TargetLanguage" text not null check("TargetLanguage" in('en','ja')),"PresentationMode" text not null default 'surface' check("PresentationMode" in('surface','surface_reading')),"AlgorithmVersion" text not null default 'P132-ALG-0.1',"InfiltrationRate" numeric(5,4) check("InfiltrationRate" is null or "InfiltrationRate" between 0 and 1),"DisplayedAt" timestamptz not null default now());
create table if not exists public."TblP132LearnerEvidence"("EvidenceID" bigint generated by default as identity primary key,"ExposureID" bigint not null references public."TblP132Exposure"("ExposureID"),"EvidenceType" text not null check("EvidenceType" in('translation_request','understand')),"OccurredAt" timestamptz not null default now(),unique("ExposureID","EvidenceType"));
create table if not exists public."TblP132LearnerVocabularyState"("UserID" uuid not null,"ConceptID" bigint not null references public."TblP132VocabularyConcept"("ConceptID"),"TargetLanguage" text not null check("TargetLanguage" in('en','ja')),"ExposureCount" integer not null default 0,"TranslationRequestCount" integer not null default 0,"UnderstandCount" integer not null default 0,"FamiliarityScore" numeric(6,4) not null default 0,"FamiliarityStage" text not null default 'new' check("FamiliarityStage" in('new','emerging','familiar','stable')),"LastExposedAt" timestamptz,"LastTranslationAt" timestamptz,"LastUnderstandAt" timestamptz,"UpdatedAt" timestamptz not null default now(),primary key("UserID","ConceptID","TargetLanguage"));
create index if not exists "IdxP132ArticlePublishedAt" on public."TblP132Article"("PublishedAt" desc);create index if not exists "IdxP132OccurrenceArticle" on public."TblP132ArticleOccurrence"("ArticleID");create index if not exists "IdxP132FormConceptLanguage" on public."TblP132VocabularyForm"("ConceptID","LanguageCode");create index if not exists "IdxP132ExposureUserConcept" on public."TblP132Exposure"("UserID","ConceptID","TargetLanguage");create index if not exists "IdxP132EvidenceExposure" on public."TblP132LearnerEvidence"("ExposureID");
